WITH with_gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM transactions), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT s.id, s.account_id, s.amount, s.txn_time, s.merchant, s.is_flagged, s.session_start_flag, CASE WHEN merchant RLIKE '^(Amazon|Lazada)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS merchant_zone, (SELECT MAX(x.amount) FROM transactions x WHERE x.account_id = s.account_id) AS max_transaction_amount FROM sessionized s ORDER BY max_transaction_amount DESC NULLS FIRST;
